using System; using Inu.Kernel.Drivers; namespace Inu.Samples.UsbDriver; public static unsafe class Sample { public static Boolean Register(out KernelDriverHandle handle){ var rule=new KernelDriverMatchRule(KernelDeviceBus.Usb,true,0,false,0,false,0x030000U,0xFF0000U); var cb=new KernelDriverCallbacks(&Probe,&Start,&Stop,&Remove,null); return KernelDrivers.RegisterDriver("sample-usb",rule,cb,out handle);} private static Boolean Probe(KernelDriverDeviceContext* c)=>c!=null; private static Boolean Start(KernelDriverDeviceContext* c)=>c!=null; private static Boolean Stop(KernelDriverDeviceContext* c)=>c!=null; private static Boolean Remove(KernelDriverDeviceContext* c)=>c!=null; }
